<section class="gmrc-campaign-register gmrc-campaign-form"><p class="gmrc-dm-desk__eyebrow">Campaign Register</p><h1>Edit <?php echo esc_html($campaign->name()); ?></h1><form method="post" action="<?php echo esc_url($action); ?>"><?php wp_nonce_field('gmrc_dm_campaign_'.$campaign->id(),'gmrc_nonce'); ?><input type="hidden" name="action" value="gmrc_app_request"><input type="hidden" name="_method" value="PUT"><input type="hidden" name="gmrc_route" value="dungeon-master/campaigns/<?php echo esc_attr($campaign->id()); ?>"><label>Campaign name<input name="name" required maxlength="100" value="<?php echo esc_attr($campaign->name()); ?>"></label><label>Campaign chronicle<textarea name="description" rows="7" maxlength="1200"><?php echo esc_textarea($campaign->description()); ?></textarea></label><button class="gmrc-campaign-button" type="submit">Save campaign</button></form><?php if(!$campaign->isArchived()): ?><form method="post" action="<?php echo esc_url($action); ?>" class="gmrc-campaign-archive"><?php wp_nonce_field('gmrc_dm_campaign_'.$campaign->id(),'gmrc_nonce'); ?><input type="hidden" name="action" value="gmrc_app_request"><input type="hidden" name="gmrc_route" value="dungeon-master/campaigns/<?php echo esc_attr($campaign->id()); ?>/archive"><button type="submit">Archive campaign</button></form><?php endif; ?></section>
